package org.example.repository;import org.example.entity.Employee;import org.springframework.stereotype.Repository;import java.util.ArrayList;import java.util.List;@Repositorypublic class EmployeeRepoImp implements EmployeeRepo {    private final List<Employee> emplist = new ArrayList<>();    @Override    public String addEmp(Employee emp) {        emplist.add(emp);        System.out.println("Employee added: " + emp.getEmp_name());        System.out.println("Employee ID: " + emp.getEmp_id());        return "Employee Added Successfully";    }    @Override    public List<Employee> getEmp() {        return emplist;    }    @Override    public Employee getEmpbyId(long emp_id) {        for (Employee emp : emplist) {            if (emp.getEmp_id() == emp_id) {                return emp;            }        }        return null;    }    @Override    public String deletebyID(long emp_id) {        for (Employee emp : emplist) {            if (emp.getEmp_id() == emp_id) {                emplist.remove(emp);                return "Employee Deleted Successfully";            }        }        return "Employee Not Found";    }    @Override    public String updatebyId(long emp_id, Employee updatedEmp) {        for (int i = 0; i < emplist.size(); i++) {            if (emplist.get(i).getEmp_id() == emp_id) {                emplist.set(i, updatedEmp);                return "Employee Updated Successfully";            }        }        return "Employee Not Found";    }}